parameters.jsCode:
const inputs = $input.all();

if (inputs.length !== 2) {
  throw new Error("Expected one response from each search branch.");
}

const sources = [
  { name: "semantic", weight: 0.6, matches: inputs[0].json.matches },
  { name: "keyword", weight: 0.4, matches: inputs[1].json.matches }
];

const combined = new Map();
const k = 60;

for (const source of sources) {
  if (!Array.isArray(source.matches)) {
    throw new Error(`Missing matches in ${source.name} response.`);
  }

  source.matches.forEach((match, index) => {
    if (!combined.has(match.id)) {
      combined.set(match.id, {
        chunk_id: match.id,
        metadata: match.metadata,
        hybrid_score: 0,
        semantic_rank: null,
        keyword_rank: null,
        semantic_score: null,
        keyword_score: null
      });
    }

    const result = combined.get(match.id);
    const rank = index + 1;

    result.hybrid_score += source.weight / (k + rank);
    result[`${source.name}_rank`] = rank;
    result[`${source.name}_score`] = match.score;
  });
}

const ranked = [...combined.values()].sort(
  (a, b) =>
    b.hybrid_score - a.hybrid_score ||
    a.chunk_id.localeCompare(b.chunk_id)
);

const selected = ranked.slice(0, 5);

return [{
  json: {
    question: $("Customer Question").first().json.chatInput,
    results: selected,
    context: selected.map(result =>
      `[${result.chunk_id}]\n` +
      `Source: ${result.metadata.source_id}\n` +
      `Title: ${result.metadata.title}\n` +
      `Type: ${result.metadata.type}\n` +
      result.metadata.text
    ).join("\n\n")
  }
}];

const response = $input.first().json;
const retrieval = $("Rank Hybrid Results").first().json;
const chunks = new Map(
  retrieval.results.map(r => [r.chunk_id, r.metadata])
);

const normalize = text => text.replace(/\s+/g, " ").trim();
const errors = [];
let draft;

try {
  draft = JSON.parse(response.choices?.[0]?.message?.content);
} catch {
  errors.push("Response could not be parsed as JSON.");
}

if (draft) {
  if (response.choices?.[0]?.finish_reason !== "stop") {
    errors.push("Model response was incomplete.");
  }

  if (!["answer", "clarify", "escalate"].includes(draft.decision)) {
    errors.push("Invalid decision.");
  }

  if (typeof draft.answer !== "string" || !draft.answer.trim()) {
    errors.push("Missing customer response.");
  }

  if (!Array.isArray(draft.citations) ||
      !Array.isArray(draft.evidence)) {
    errors.push("Missing citations or evidence arrays.");
  } else {
    for (const id of draft.citations) {
      if (!chunks.has(id)) errors.push(`Unknown citation: ${id}`);
    }

    for (const e of draft.evidence) {
  const chunk = chunks.get(e.chunk_id);

  if (!chunk || typeof e.quote !== "string" || !e.quote.trim()) {
    errors.push(`Invalid evidence: ${e.chunk_id}`);
    continue;
  }

  const excerpts = normalize(e.quote).split(/(?<=[.!?])\s+/);
  const sourceText = normalize(chunk.text);

  for (const excerpt of excerpts) {
    if (!sourceText.includes(excerpt)) {
      errors.push(`Evidence sentence not found: ${e.chunk_id}`);
    }
  }
}

    if (draft.decision === "answer") {
      if (draft.evidence_sufficient !== true ||
          draft.citations.length === 0) {
        errors.push("Answer lacks supporting evidence.");
      }

      for (const id of draft.citations) {
        if (!draft.answer?.includes(`[${id}]`)) {
          errors.push(`Citation missing from answer: ${id}`);
        }

        if (!draft.evidence.some(e => e.chunk_id === id)) {
          errors.push(`Citation lacks an evidence quote: ${id}`);
        }
      }

      const authoritative = draft.evidence.some(e =>
        ["policy", "manual", "faq"].includes(chunks.get(e.chunk_id)?.type)
      );

      if (!authoritative) {
        errors.push("Answer lacks an authoritative source.");
      }
    }
  }
}

const valid = errors.length === 0;

return [{
  json: {
    question: retrieval.question,
    decision: valid ? draft.decision : "escalate",
    output: valid
      ? draft.answer
      : "I couldn't verify a reliable answer from the available sources. Human support needs to review this question.",
    reason: valid ? draft.reason : errors.join(" "),
    citations: valid ? draft.citations : [],
    validation_passed: valid,
    validation_errors: errors
  }
}];

